// Text — a run of type set in one of the system's type roles, the unit a screen writes a heading or
// a paragraph with. Category A: React Aria's `Text`, so it also answers a `TextContext` slot, but only
// one it is given by name: a run of type is placed anywhere (inside a field's trailing slot, a list
// item), and React Aria throws for an unnamed Text in a context that offers only named slots, which
// takes the whole page down.
// The role class carries the type (component-contract.md §6 carve-out 4). Colour is inherited, as
// text on its surface reads by default (naming-convention.md § Text colour roles, row 12), unless
// `tone="muted"` marks a supporting line (row 4) or `tone="emphasis"` a mark the product flags with
// no status attached (row 10), each read from the `text` domain's Cmp tokens.
import { Text as AriaText, TextContext } from "react-aria-components";
import type { TextProps as AriaTextProps } from "react-aria-components";
import type { Ref } from "react";
import "./Text.css";

export type TextVariant = "display" | "headline" | "title" | "subtitle" | "body" | "label" | "caption" | "code";

export interface TextProps extends Omit<AriaTextProps, "className" | "elementType" | "slot"> {
  /**
   * The type role, chosen by what the text does (naming-convention.md § Role assignment): `title`
   * names a view or section, `body` is reading content or a value, `label` names a control or a
   * value, `caption` annotates something else, `subtitle` heads a compact unit, `display` and
   * `headline` are hero-scale, `code` is monospace.
   *
   * @default "body"
   */
  variant?: TextVariant;
  /**
   * The role's size. `medium` unless a prop drives it or the text reads one rung below a partner
   * seen with it (naming-convention.md § The size axis).
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /**
   * The role's emphasized twin: the same size, one weight rung heavier (ADR-0027). For a run that
   * stresses part of a line, prefer a `strong` inside the text, which carries the emphasized role
   * of its own line.
   *
   * @default false
   */
  isEmphasized?: boolean;
  /**
   * `muted` for a supporting line under a primary text on the same surface (a description under a
   * title, a sub-line under a value), so the two are told apart by colour as well as size
   * (naming-convention.md § Text colour roles, row 4). `emphasis` for a mark the product flags for
   * attention with no status attached: a sale price, a saving, the phrase a heading turns on (row 10);
   * an error or a warning is a status and is not this. `urgency` for a reason to act now with no status
   * attached: a discount rate, a deal ending (row 11). `default` inherits the surface's ink.
   *
   * @default "default"
   */
  tone?: "default" | "muted" | "emphasis" | "urgency";
  /**
   * Clamps the text to this many lines and ends the last one with an ellipsis: a review body at 3,
   * a product name at 2, an article card's title at 1 or 2. Unset, the text wraps in full. A clamped
   * run is drawn as a block box (`-webkit-box`), so a clamped `span` no longer flows inline.
   */
  maxLines?: 1 | 2 | 3;
  /**
   * The element it renders. A heading is an `h1`–`h6` by its place in the page's outline, never by
   * its look; the look is `variant` and `size`.
   *
   * @default "p"
   */
  elementType?: "p" | "span" | "div" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  /**
   * The `TextContext` slot it fills, such as `description` inside a field. Without one it joins no
   * context and keeps its own role.
   */
  slot?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function Text({
  variant = "body",
  size = "medium",
  isEmphasized = false,
  tone = "default",
  maxLines,
  elementType = "p",
  slot,
  className,
  ...props
}: TextProps) {
  const cls = `sd-text sd-type-${variant}-${size}${isEmphasized ? "-emphasized" : ""}`;
  const text = (
    <AriaText
      {...props}
      slot={slot}
      elementType={elementType}
      data-tone={tone === "default" ? undefined : tone}
      data-max-lines={maxLines}
      className={className ? `${cls} ${className}` : cls}
    />
  );
  // Unnamed, it reads no context at all, so no field or list item can claim or refuse it.
  return slot ? text : <TextContext.Provider value={null}>{text}</TextContext.Provider>;
}

/* Text.css — .sd-text
   The role class on the same element (sd-type-<role>-<size>) sets the type; this rule only clears the
   user agent's block margins on p and h1–h6, so a copy without reset.css sits where the layout puts
   it (component-contract.md §9). */
.sd-text {
  margin: 0;
}
/* A supporting line (`tone="muted"`) takes the muted ink, naming-convention.md § Text colour roles
   row 4; the default tone inherits. */
.sd-text[data-tone="muted"] {
  color: var(--sd-text-muted-foreground);
}
/* A mark the product flags with no status attached (`tone="emphasis"`), row 10 of the same table. */
.sd-text[data-tone="emphasis"] {
  color: var(--sd-text-emphasis-foreground);
}
/* A reason to act now with no status attached (`tone="urgency"`), row 11 of the same table. */
.sd-text[data-tone="urgency"] {
  color: var(--sd-text-urgency-foreground);
}
/* `maxLines` clamps the run to N lines with an ellipsis. `-webkit-line-clamp` is the shipped
   mechanism in every engine; the unprefixed `line-clamp` takes over where it lands. */
.sd-text[data-max-lines] {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.sd-text[data-max-lines="1"] {
  -webkit-line-clamp: 1;
  line-clamp: 1;
}
.sd-text[data-max-lines="2"] {
  -webkit-line-clamp: 2;
  line-clamp: 2;
}
.sd-text[data-max-lines="3"] {
  -webkit-line-clamp: 3;
  line-clamp: 3;
}
